import dns_codec as d

A = {"name":"a.","type":1,"class":1,"ttl":100,"address":"1.2.3.4"}

# 64-bit boundaries
r = d.lookup_cache([A], 0, 2**64-1, "a.", 1, 1)
assert r == {"status":"miss","records":[],"expired":1}
r = d.lookup_cache([A], 2**64-1, 2**64-1, "a.", 1, 1)
assert r["status"] == "hit" and r["records"][0]["ttl"] == 100

# qtype/qclass boundaries
assert d.lookup_cache([A], 0, 0, "a.", 1, 2**16-1)["status"] == "miss"
for bad in [1.0, "1", None, [1]]:
    try:
        d.lookup_cache([A], 0, 0, "a.", bad, 1)
        raise AssertionError("qtype accepted: %r" % bad)
    except d.DNSArgumentError:
        pass
    try:
        d.lookup_cache([A], 0, 0, "a.", 1, bad)
        raise AssertionError("qclass accepted: %r" % bad)
    except d.DNSArgumentError:
        pass
    try:
        d.lookup_cache([A], bad, 0, "a.", 1, 1)
        raise AssertionError("stored_at accepted: %r" % bad)
    except d.DNSArgumentError:
        pass

# qname type/shape errors
for bad in [1, b"a.", None, "a..", ".a", "a", "A"*64+".", "ä."]:
    try:
        d.lookup_cache([A], 0, 0, bad, 1, 1)
        raise AssertionError("qname accepted: %r" % bad)
    except d.DNSArgumentError:
        pass

# records wrong shape
for bad in ({}, "x", 1, None, iter([A])):
    try:
        d.lookup_cache(bad, 0, 0, "a.", 1, 1)
        raise AssertionError("records accepted: %r" % bad)
    except d.DNSArgumentError:
        pass

# expired counted even when all matches miss; class-1 expired record still counted
B = dict(A, ttl=1)
r = d.lookup_cache([A, B], 0, 50, "a.", 28, 1)
assert r == {"status":"miss","records":[],"expired":1}, r

# non-matching types are NOT counted as expired; matching name+class diff type stays alive
r = d.lookup_cache([dict(A, type=28, address="::1")], 0, 0, "a.", 1, 1)
assert r == {"status":"miss","records":[],"expired":0}

# full snapshot validated even if an early record would match (no partial result)
badrec = {"name":"a.","type":1,"class":1,"ttl":1,"address":"x"}
try:
    d.lookup_cache([A, badrec], 0, 0, "a.", 1, 1)
    raise AssertionError("should have raised")
except d.DNSArgumentError:
    pass

print("boundary/type validation OK")
EOF
